/* Reuse the exact existing Compact trust, credential and warm implementation.
   No source rewriting: this translation unit also exports compact_client/server.
   PCMA registers a separate extension and separate verification callbacks. */
#include "../../../compact/compact.c"
#include "tls.h"
#define PC_EXT 0xffa7u
typedef struct { Config *c; PcCache cache; char *path; } PcContext;
typedef struct { PcMetrics m; unsigned char available[PC_MAX]; PcCache *pending; int authenticated,committed; } PcState;
static int pci=-1,psi=-1;
static void pc_context_free(void *parent,void *ptr,CRYPTO_EX_DATA *ad,int idx,long l,void *arg){PcContext *p=ptr;(void)parent;(void)ad;(void)idx;(void)l;(void)arg;if(p){OPENSSL_free(p->path);OPENSSL_free(p);}}
static void pc_state_free(void *parent,void *ptr,CRYPTO_EX_DATA *ad,int idx,long l,void *arg){PcState *p=ptr;(void)parent;(void)ad;(void)idx;(void)l;(void)arg;if(p){OPENSSL_free(p->pending);OPENSSL_free(p);}}
static PcState *pc_state(SSL *ssl){PcState *p=SSL_get_ex_data(ssl,psi);if(!p){p=OPENSSL_zalloc(sizeof(*p));if(p&&!SSL_set_ex_data(ssl,psi,p)){OPENSSL_free(p);p=NULL;}}return p;}
static int pc_add(SSL *ssl,unsigned type,unsigned context,const unsigned char **out,size_t *len,X509 *x,size_t index,int *alert,void *arg){PcContext *pc=arg;Config *c=pc->c;State *s=state(ssl);PcState *ps=pc_state(ssl);unsigned char *p;(void)type;(void)x;(void)index;*alert=SSL_AD_INTERNAL_ERROR;if(!s||!ps)return -1;p=OPENSSL_malloc(PC_WIRE);if(!p)return -1;if(!c->server&&context==SSL_EXT_CLIENT_HELLO){double start=pc_clock();/* Explicit caller-selected authority/root + verified hostname, no opportunistic offer. */if(!pc_encode(&pc->cache,p,PC_WIRE,len)){OPENSSL_free(p);return -1;}ps->m.encode_ms=pc_clock()-start;ps->m.advertised=*len;*out=p;return 1;}if(c->server&&context==SSL_EXT_TLS1_3_ENCRYPTED_EXTENSIONS&&s->offered){State full={0};const unsigned char *unused;size_t unused_len,partial_len;if(!bundle_decode(c->bundle,c->bundle_len,&full,&unused,&unused_len)){OPENSSL_free(p);return -1;}memcpy(p,"PCB1",4);put16(p+4,full.credential_len);memcpy(p+6,full.credential,full.credential_len);size_t offset=6+full.credential_len;if(!pc_partial(&full.proof,ps->available,p+offset+2,PC_WIRE-offset-2,&partial_len,&ps->m)){OPENSSL_free(p);return -1;}put16(p+offset,partial_len);*len=offset+2+partial_len;ps->m.credential_bytes=full.credential_len;*out=p;return 1;}OPENSSL_free(p);return 0;}
static int pc_parse(SSL *ssl,unsigned type,unsigned context,const unsigned char *p,size_t n,X509 *x,size_t index,int *alert,void *arg){PcContext *pc=arg;Config *c=pc->c;State *s=state(ssl);PcState *ps=pc_state(ssl);(void)type;(void)x;(void)index;*alert=SSL_AD_BAD_CERTIFICATE;if(!s||!ps)return 0;if(c->server&&context==SSL_EXT_CLIENT_HELLO){double start=pc_clock();if(s->offered||!pc_decode(p,n,&c->root,ps->available))return 0;ps->m.parse_ms=pc_clock()-start;ps->m.advertised=n;s->offered=1;return 1;}if(c->server||context!=SSL_EXT_TLS1_3_ENCRYPTED_EXTENSIONS||s->received||n<8||n>PC_WIRE||memcmp(p,"PCB1",4))return 0;size_t cl=u16(p+4),o=6+cl;if(cl<56||cl>MAX_CREDENTIAL||n<o+2||u16(p+o)!=n-o-2)return 0;memcpy(s->credential,p+6,cl);s->credential_len=cl;s->root=c->root;s->root_nb=c->root_nb;s->root_na=c->root_na;if(!pc_reconstruct(p+o+2,n-o-2,&pc->cache,&s->proof,&ps->m))return 0;ps->m.credential_bytes=cl;s->received=1;return 1;}
static int pc_verify(X509_STORE_CTX *store,void *arg){PcContext *pc=arg;SSL *ssl=X509_STORE_CTX_get_ex_data(store,SSL_get_ex_data_X509_STORE_CTX_idx());State *s=ssl?state(ssl):NULL;PcState *ps=ssl?pc_state(ssl):NULL;EVP_PKEY *key=X509_STORE_CTX_get0_rpk(store);double start=pc_clock();if(!s||!ps||!s->received||!key||SSL_get_negotiated_server_cert_type(ssl)!=TLSEXT_cert_type_rpk||!credential_verify(pc->c,s,key))goto fail;ps->m.credential_verify_ms=pc_clock()-start;ps->pending=OPENSSL_memdup(&pc->cache,sizeof(pc->cache));if(!ps->pending||!pc_learn(ps->pending,s->credential,s->credential_len,&s->proof,&ps->m))goto fail;/* Pending is not persisted until SSL_connect returns success (CV + Finished). */ps->authenticated=1;X509_STORE_CTX_set_error(store,X509_V_OK);return 1;fail:X509_STORE_CTX_set_error(store,X509_V_ERR_APPLICATION_VERIFICATION);return 0;}
static int pc_install(SSL_CTX *ctx,PcContext *pc){const unsigned char rpk[]={TLSEXT_cert_type_rpk};if(ci<0)ci=SSL_CTX_get_ex_new_index(0,NULL,NULL,NULL,config_free);if(si<0)si=SSL_get_ex_new_index(0,NULL,NULL,NULL,state_free);if(pci<0)pci=SSL_CTX_get_ex_new_index(0,NULL,NULL,NULL,pc_context_free);if(psi<0)psi=SSL_get_ex_new_index(0,NULL,NULL,NULL,pc_state_free);if(ci<0||si<0||pci<0||psi<0||!SSL_CTX_set_min_proto_version(ctx,TLS1_3_VERSION)||!SSL_CTX_set_max_proto_version(ctx,TLS1_3_VERSION)||!SSL_CTX_set1_server_cert_type(ctx,rpk,sizeof(rpk)))return 0;SSL_CTX_set_options(ctx,SSL_OP_NO_TICKET);SSL_CTX_set_session_cache_mode(ctx,SSL_SESS_CACHE_OFF);if(!SSL_CTX_set_num_tickets(ctx,0)||!SSL_CTX_add_custom_ext(ctx,PC_EXT,CONTEXT,pc_add,free_ext,pc,pc_parse,pc))return 0;if(!SSL_CTX_set_ex_data(ctx,ci,pc->c)||!SSL_CTX_set_ex_data(ctx,pci,pc))return 0;if(!pc->c->server){SSL_CTX_set_verify(ctx,SSL_VERIFY_PEER,NULL);SSL_CTX_set_cert_verify_callback(ctx,pc_verify,pc);}return 1;}
int pcma_client(SSL_CTX *ctx,const char *authority,const char *root,const char *cache,unsigned budget,unsigned policy){BIO *bio=NULL;X509 *ca=NULL;PcContext *pc=OPENSSL_zalloc(sizeof(*pc));const char *host=X509_VERIFY_PARAM_get0_host(SSL_CTX_get0_param(ctx),0);if(!pc)return 0;pc->c=OPENSSL_zalloc(sizeof(Config));Config *c=pc->c;if(!c||!authority||!root||!cache||!host||strlen(host)>253||policy>1||budget>69*PC_MAX||X509_VERIFY_PARAM_get0_host(SSL_CTX_get0_param(ctx),1))goto fail;for(size_t i=0;host[i];i++)c->hostname[i]=host[i]>='A'&&host[i]<='Z'?host[i]+32:host[i];if(!dns_name((unsigned char*)c->hostname,strlen(c->hostname)))goto fail;bio=BIO_new_file(authority,"r");if(!bio||!(ca=PEM_read_bio_X509(bio,NULL,NULL,NULL))||X509_check_ca(ca)<=0)goto fail;c->authority=X509_get_pubkey(ca);c->authority_nb=asn1_epoch(X509_get0_notBefore(ca));c->authority_na=asn1_epoch(X509_get0_notAfter(ca));if(!supported_key(c->authority)||!hash_key(c->authority,c->authority_id)||!valid_time(c->authority_nb,c->authority_na)||!mt_read_file(root,c->signed_root,sizeof(c->signed_root),&c->signed_len)||!root_decode(c,c->signed_root,c->signed_len,&c->root,&c->root_nb,&c->root_na,1)||!pc_total(c->root.leaves))goto fail;c->warm=1;pc->cache.tree=c->root;pc->cache.budget=budget;pc->cache.policy=policy;pc->path=OPENSSL_strdup(cache);if(!pc->path||!pc_load(&pc->cache,cache))goto fail;X509_free(ca);BIO_free(bio);return pc_install(ctx,pc);fail:X509_free(ca);BIO_free(bio);config_free(NULL,c,NULL,0,0,NULL);pc_context_free(NULL,pc,NULL,0,0,NULL);return 0;}
int pcma_server(SSL_CTX *ctx,const char *bundle,const char *signed_root){PcContext *pc=OPENSSL_zalloc(sizeof(*pc));State full={0};const unsigned char *unused;size_t unused_len;if(!pc)return 0;pc->c=OPENSSL_zalloc(sizeof(Config));Config *c=pc->c;if(!c)goto fail;c->server=1;if(!mt_read_file(bundle,c->bundle,sizeof(c->bundle),&c->bundle_len)||!bundle_decode(c->bundle,c->bundle_len,&full,&unused,&unused_len)||unused_len||!mt_read_file(signed_root,c->signed_root,sizeof(c->signed_root),&c->signed_len)||!root_decode(c,c->signed_root,c->signed_len,&c->root,&c->root_nb,&c->root_na,0)||!pc_total(c->root.leaves)||!mt_proof_verify(full.credential,full.credential_len,&full.proof,&c->root))goto fail;return pc_install(ctx,pc);fail:config_free(NULL,c,NULL,0,0,NULL);pc_context_free(NULL,pc,NULL,0,0,NULL);return 0;}
int pcma_finish(SSL *ssl){PcContext *pc=pci<0?NULL:SSL_CTX_get_ex_data(SSL_get_SSL_CTX(ssl),pci);if(!pc)return 1;PcState *ps=pc_state(ssl);State *s=state(ssl);if(!ps||!s||!SSL_is_init_finished(ssl)||SSL_session_reused(ssl))return 0;if(pc->c->server)return s->offered;if(!ps->authenticated||!ps->pending||ps->committed)return 0;if(!pc_save(ps->pending,pc->path))return 0;pc->cache=*ps->pending;ps->committed=1;return 1;}
const PcMetrics *pcma_metrics(SSL *ssl){if(psi<0)return NULL;PcState *ps=SSL_get_ex_data(ssl,psi);PcContext *pc=SSL_CTX_get_ex_data(SSL_get_SSL_CTX(ssl),pci);if(ps&&pc&&!pc->c->server&&!ps->committed){ps->m.cache_nodes=pc->cache.count;ps->m.cache_bytes=pc->cache.count*69;ps->m.added=ps->m.evicted=0;}return ps?&ps->m:NULL;}

int compact_observation(SSL *ssl,PcMetrics *m){Config *c=ci<0?NULL:SSL_CTX_get_ex_data(SSL_get_SSL_CTX(ssl),ci);State *s=si<0?NULL:SSL_get_ex_data(ssl,si);if(!c||!s||!s->received)return 0;m->credential_bytes=s->credential_len;m->proof_bytes=45+32*s->proof.depth;m->normal=s->proof.depth;m->sent=m->normal;return 1;}
